out=[]
import re,datetime
for n,(t,c,res,summ,tools,agent,inds,diff,st,cost,imp,prompt) in enumerate(rows):
    slug=re.sub(r'[^a-z0-9]+','-',t.lower()).strip('-')
    out.append(dict(slug=slug,title=t,category=C[c],result=res,summary=summ,
      what_they_did=f"{summ} The owner started with a small pilot: one workflow, a few days of supervised use where every output was reviewed before it went out, then gradually let routine cases run with lighter oversight.",
      how_it_went=f"In a typical rollout like this: {res.lower()}. Most of the value comes from consistency, the task happens every time instead of when someone remembers. Expect a week or two of tuning the prompt and rules.",
      worth_knowing="AI drafts can be wrong or off-tone. Keep a human approving anything customer-facing at first, don't paste sensitive data (card numbers, health records, SSNs) into general chat tools, and check each tool's data and privacy terms.",
      prompt=prompt,
      steps=[f"Write down how you handle this today, in 5-10 bullets.",f"Connect or export data from {', '.join(tools)}.",f"Set up {agent} and paste in the prompt, filling in the [placeholders].","Test it on 5-10 real past examples and fix anything that's off.","Run it with you approving every output for one to two weeks.","Once you trust it, automate the routine cases and spot-check weekly."],
      video_url=None,tools=tools,agent=agent,industries=[I[i] for i in inds],difficulty=diff,setup_time=st,monthly_cost=cost,impact=imp,source_url=None,
      published_at=(datetime.date(2026,10,13)-datetime.timedelta(days=n)).isoformat(),is_example=True))
json.dump(out,open('data/use-cases.json','w'),indent=2)
print(len(out))
